        String[] parts = line.split(",", -1);
        long ts = parseLong(parts, 0);
        long job = parseLong(parts, 2);
        long task = parseLong(parts, 3);
        int type = parseInt(parts, 5);
        return new TaskEvent(ts, job, task, type);
    }

    private static long parseLong(String[] parts, int idx) {
        if (idx < 0 || idx >= parts.length) {
            return -1L;
        }
        String v = parts[idx];
        if (v == null) {
            return -1L;
        }
        v = v.trim();
        if (v.isEmpty()) {
            return -1L;
        }
        return Long.parseLong(v);
